(function(){
  let trees=[];
  const treeCount=14;
  for(let i=0;i<treeCount;i++){
    trees.push({x:Math.random(),h:0.15+Math.random()*0.25,w:0.04+Math.random()*0.05,phase:Math.random()*Math.PI*2,depth:Math.random()});
  }
  let fog=[];
  const fogCount=60;
  for(let i=0;i<fogCount;i++){
    fog.push({x:Math.random(),y:Math.random(),r:20+Math.random()*50,speed:0.02+Math.random()*0.03,phase:Math.random()*Math.PI*2,alpha:0.03+Math.random()*0.05});
  }
  const ribbons=[
    {color:PALETTE[0],amp:60,freq:1.3,speed:0.15,yOff:0.25,phase:0,widthBase:26},
    {color:PALETTE[1],amp:80,freq:1.0,speed:0.1,yOff:0.55,phase:2,widthBase:34},
    {color:PALETTE[2],amp:50,freq:1.6,speed:0.2,yOff:0.78,phase:4,widthBase:20}
  ];
  function drawTrees(time){
    const w=W(),h=H();
    ctx.save();
    for(let i=0;i<trees.length;i++){
      const tr=trees[i];
      const sway=Math.sin(time*0.0003+tr.phase)*6*(1-tr.depth);
      const baseX=tr.x*w+sway;
      const baseY=h*0.92-tr.depth*h*0.05;
      const trunkH=tr.h*h;
      const trunkW=tr.w*w;
      const alpha=0.10+0.16*(1-tr.depth);
      ctx.beginPath();
      ctx.moveTo(baseX,baseY);
      ctx.quadraticCurveTo(baseX-trunkW*0.6,baseY-trunkH*0.5,baseX,baseY-trunkH);
      ctx.quadraticCurveTo(baseX+trunkW*0.6,baseY-trunkH*0.5,baseX,baseY);
      ctx.fillStyle = DARK ? 'rgba(20,25,20,'+alpha+')' : 'rgba(70,75,65,'+alpha+')';
      ctx.fill();
    }
    ctx.restore();
  }
  function drawFog(time){
    const w=W(),h=H();
    for(let i=0;i<fog.length;i++){
      const f=fog[i];
      const fx=((f.x*w+Math.sin(time*0.0002+f.phase)*30)%w+w)%w;
      const fy=((f.y*h-(time*f.speed*0.02)%h)+h*2)%h;
      const grad=ctx.createRadialGradient(fx,fy,0,fx,fy,f.r);
      grad.addColorStop(0,'rgba(255,255,255,'+f.alpha+')');
      grad.addColorStop(1,'rgba(255,255,255,0)');
      ctx.fillStyle=grad;
      ctx.beginPath();
      ctx.arc(fx,fy,f.r,0,Math.PI*2);
      ctx.fill();
    }
  }
  function distFromCenter(x,y,w,h){
    const cx=w/2,cy=h/2;
    return Math.hypot(x-cx,y-cy);
  }
  function hexA(hex,a){
    return hex + a;
  }
  function drawRibbon(rb,time){
    const w=W(),h=H();
    const cx=w/2,cy=h/2;
    const safeR=Math.min(w,h)*0.22;
    ctx.save();
    ctx.lineCap='round';
    ctx.lineJoin='round';
    const points=[];
    const steps=70;
    for(let i=0;i<=steps;i++){
      const p=i/steps;
      const x=p*w*1.1-w*0.05;
      let y=h*rb.yOff+Math.sin(p*Math.PI*rb.freq*2+time*rb.speed*0.001+rb.phase)*rb.amp;
      const d=distFromCenter(x,y,w,h);
      if(d<safeR){
        const angle=Math.atan2(y-cy,x-cx);
        const push=safeR-d;
        y += Math.sin(angle)*push*1.4;
      }
      points.push({x:x,y:y});
    }
    ctx.beginPath();
    for(let i=0;i<points.length;i++){
      const widthMod=rb.widthBase*(0.6+0.4*Math.sin(points[i].x*0.01+time*0.0005));
      const nx=points[i].x, ny=points[i].y-widthMod;
      if(i===0) ctx.moveTo(nx,ny); else ctx.lineTo(nx,ny);
    }
    for(let i=points.length-1;i>=0;i--){
      const widthMod=rb.widthBase*(0.6+0.4*Math.sin(points[i].x*0.01+time*0.0005));
      const nx=points[i].x, ny=points[i].y+widthMod;
      ctx.lineTo(nx,ny);
    }
    ctx.closePath();
    const grad=ctx.createLinearGradient(0,0,w,h);
    grad.addColorStop(0,hexA(rb.color,'cc'));
    grad.addColorStop(0.5,hexA(rb.color,'55'));
    grad.addColorStop(1,hexA(rb.color,'cc'));
    ctx.fillStyle=grad;
    ctx.shadowColor=rb.color;
    ctx.shadowBlur=25;
    ctx.globalAlpha=0.5;
    ctx.fill();
    ctx.restore();
  }
  function frame(ts){
    const w=W(),h=H();
    ctx.clearRect(0,0,w,h);
    drawTrees(ts);
    for(let i=0;i<ribbons.length;i++) drawRibbon(ribbons[i],ts);
    drawFog(ts);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
